class Solution {
public:
    int countCompleteSubarrays(vector<int>& nums) {
        int n = nums.size();
        bool present[2001] = {false};
        int k = 0;
        for (int x : nums) {
            if (!present[x]) {
                present[x] = true;
                k++;
            }
        }

        int freq[2001] = {0};
        int left = 0, distinct = 0;
        long long ans = 0;

        for (int right = 0; right < n; right++) {
            freq[nums[right]]++;
            if (freq[nums[right]] == 1) distinct++;

            while (distinct == k) {
                ans += n - right;
                freq[nums[left]]--;
                if (freq[nums[left]] == 0) distinct--;
                left++;
            }
        }

        return (int)ans;
    }
};
